window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes"]={"block":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","label":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","count":54,"questions":[{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-736faf2bef28848f","number":"1009b","sourceNumber":"1009b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"Assinale a alternativa que apresenta a razão para a utilização de anticoagulante injetável concomitante ao início da terapia por warfarina na anticoagulação.","options":{"A":"A warfarina bloqueia a ativação de fatores da cascata de coagulação e a produção dos inibidores de coagulação (proteína C e S) dependentes da vitamina K.","B":"Não se pode confiar na absorção oral da warfarina, sendo esse o motivo pelo qual há tanta variabilidade no resultado do tempo de protrombina.","C":"O uso de anticoagulantes parenterais traz benefício na terapêutica intra-hospitalar pela sua fácil via de administração.","D":"A warfarina é uma pró-droga que chega inativada ao fígado, pelo contato com as proteínas C e S, sendo somente ativada após o efeito de primeira passagem pela enzima P450."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"Atenção: o gabarito antigo aqui estava errado (marcava D); a resposta certa é A. A explicação é essa: quando a pessoa começa a tomar varfarina, o remédio bloqueia a fábrica de vários fatores de coagulação, mas também bloqueia duas 'proteínas de freio' do próprio corpo (proteína C e S), que têm vida curta e caem rapidinho. Por alguns dias, o corpo fica sem esse freio, mas os fatores que fazem o sangue coagular ainda demoram a cair — ou seja, no começo, a varfarina pode até deixar o sangue MAIS propenso a coagular! É por isso que se usa um anticoagulante injetável junto (tipo heparina) logo no início, pra proteger o paciente nesses primeiros dias perigosos.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439651969","ankiGuid":"P)gP)zv-?O"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-1f3d803499e7a59a","number":"1010b","sourceNumber":"1010b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"Um homem de 78 anos, obeso, recebe enoxaparina profilática no pós-operatório de artroplastia de quadril. No 6º dia após o início do anticoagulante, detecta-se plaquetopenia de 50 mil/microL, caindo para 40 mil no dia seguinte. A conduta mais adequada é:","options":{"A":"Trocar heparina de baixo peso molecular por heparina não fracionada em dose plena.","B":"Suspender heparina e iniciar fondaparinux.","C":"Apenas observar, com contagem diária de plaquetas e suspender heparina se cair abaixo de 10 mil/microL.","D":"Manter enoxaparina na dose profilática e administrar corticosteroide 1 mg/kg/dia IV.","E":"Suspender enoxaparina e iniciar heparina não fracionada em dose profilática."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"Atenção: o gabarito antigo marcava D (manter a heparina e dar corticoide), o que é perigoso — nunca se deve manter a heparina quando se suspeita de HIT (trombocitopenia induzida por heparina)! A resposta certa é B: suspender toda heparina (mesmo a de baixo peso molecular) e trocar por outro anticoagulante que não seja da família da heparina, como o fondaparinux, porque o corpo desenvolveu anticorpos contra a heparina que estão destruindo as plaquetas.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439651970","ankiGuid":"ldo>=g)}d3"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-c18ac0bc67b2eb82","number":"1011b","sourceNumber":"1011b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"A corrida pelo desenvolvimento de vacinas contra o SARS-CoV-2 resultou na rápida aprovação de imunizantes pelas agências regulatórias. Infelizmente, isto aumentou as chances de aparecimento de efeitos colaterais inicialmente não descritos nos estudos. Um dos eventos mais graves foi a Trombocitopenia Trombótica Induzida por Vacina (VfTT). Esta complicação lembra muito a fisiopatologia da Trombocitopenia Induzida pela Heparina (HIT), cujo principal anticorpo envolvido é:","options":{"A":"Anti-C5;","B":"Anti-PF4;","C":"Anti-glicoproteína IIB/IIIa;","D":"ADAMTS-13;","E":"Anti-CD55 e 59."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"A VITT (trombose e trombocitopenia após vacina) se parece muito com a HIT (a reação ruim que a heparina pode causar) porque as duas têm o mesmo tipo de anticorpo culpado: o anti-PF4 (contra o 'fator plaquetário 4'). Esse anticorpo confunde o sistema imune e faz ele atacar as próprias plaquetas, causando ao mesmo tempo plaquetas baixas E coágulos — uma combinação perigosa.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439651971","ankiGuid":"f*mv5jX]Jl"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-f0c1c646e7d55c66","number":"1012b","sourceNumber":"1012b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"Um paciente de 59 anos de idade foi à consulta, no ambulatório de clínica médica, para controle do tempo de protrombina/INR pelo uso de warfarina, devido à fibrilação atrial crônica, e pediu exemplos de alimentos que deveria evitar. Com base nesse caso hipotético, assinale a alternativa que apresenta todos os alimentos que deverão ser evitados.","options":{"A":"Agrião, palmito e suco de cranberry","B":"Espinafre, tomate e suco de laranja","C":"Couve-flor, cenoura e suco de limão","D":"Nabo, repolho e suco de uva","E":"Alface, brócolis e chá verde"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"Quem toma varfarina precisa manter uma quantidade ESTÁVEL de vitamina K na alimentação, e os maiores 'vilões' de vitamina K são os vegetais verde-escuros e crucíferos, como repolho e nabo. O suco de uva também pode interferir na forma como o corpo processa a varfarina. Comer esses alimentos de vez em quando, em quantidades variáveis, é o que mais atrapalha o controle do INR — o ideal não é nunca comer, e sim comer sempre a mesma quantidade.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439651972","ankiGuid":"CRZRhYO9p%"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-4e46bd3897357c31","number":"1013b","sourceNumber":"1013b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"Um paciente adulto em uso de warfarina realizou dosagem de Tempo de Atividade de Protrombina (TAP) que apresentou resultado de Relação Normatizada Internacional (RNI) igual a 8. O paciente não apresenta sangramento, equimoses ou hematomas. Nesse caso, a conduta correta a ser adotada é:","options":{"A":"Suspender a warfarina, administrar vitamina K intramuscular e reintroduzir warfarina quando o RNI estiver abaixo de 2.","B":"Reduzir a dose de warfarina em 50% e reavaliar o paciente ambulatorialmente em uma semana com novo TAP/RNI.","C":"Suspender a warfarina, administrar plasma fresco e reintroduzir warfarina com dose ajustada no dia seguinte.","D":"Reduzir a dose de warfarina em 25%, administrar vitamina K via oral e reavaliar o paciente em uma semana com novo TAP/RNI.","E":"Suspender a warfarina e monitorar o TAP/RNI, reintroduzindo a warfarina em dose reduzida, assim que o RNI voltar à faixa terapêutica indicada."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"Quando o RNI fica muito alto (aqui, 8) mas o paciente não está sangrando, a conduta é reduzir/segurar a varfarina e dar uma dose de vitamina K por via oral (que funciona bem e com menos risco que a via venosa) — isso ajuda o corpo a voltar a produzir os fatores de coagulação aos poucos, evitando um sangramento futuro, sem precisar de nada mais agressivo como plasma.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439651973","ankiGuid":"qM/id!kW^n"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-1ff96ee341d908b7","number":"1014b","sourceNumber":"1014b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"Com relação às indicações dos anticoagulantes, assinale a alternativa correta:","options":{"A":"A rivaroxabana foi aprovada para reduzir o risco de AVC e embolia sistêmica em pacientes com FA de etiologia não valvar.","B":"O edoxaban pode ser utilizado indiscriminadamente e com segurança, mesmo em paciente com insuficiência hepática.","C":"Pacientes com embolia pulmonar não podem ser tratados com rivaroxabana.","D":"O apixabana somente deve ser utilizado em pacientes com embolia sistêmica e FA de etiologia valvar."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"Atenção: o gabarito antigo marcava B, que é uma afirmação falsa (edoxabana NÃO pode ser usada livremente em quem tem problema no fígado — ela é contraindicada em disfunção hepática significativa). A resposta certa é A: a rivaroxabana realmente foi aprovada e é bastante usada para prevenir AVC e embolia em pacientes com fibrilação atrial que NÃO é causada por problema na válvula do coração (não-valvar).","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439651974","ankiGuid":"M%>a4#=|d;"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-ef4acb782a0fb130","number":"1015b","sourceNumber":"1015b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"Qual proteína é o mediador primário da adesão plaquetária?","options":{"A":"Colágeno.","B":"Endotelina.","C":"Fator tissular.","D":"Trombina.","E":"Fator de Von Willebrand."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"Atenção: o gabarito antigo marcava B ('Endotelina'), que não tem nada a ver com isso — endotelina é um hormônio que contrai vasos sanguíneos. A resposta certa é E: o Fator de Von Willebrand funciona como uma 'cola' que gruda a plaqueta na parede do vaso machucado, sendo o principal responsável por essa primeira etapa (adesão) da coagulação.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439651975","ankiGuid":"B[.x-(k#;l"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-6c28463a626c0f1a","number":"1016b","sourceNumber":"1016b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"A heparina de baixo peso molecular possui como um mecanismo de ação a inibição do fator:","options":{"A":"Xa.","B":"IXa.","C":"VIIa.","D":"Va.","E":"IVa."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"A heparina de baixo peso molecular age principalmente bloqueando o fator Xa (com uma ajudinha da antitrombina do próprio corpo) — por isso ela não costuma precisar de exame de sangue pra ajustar a dose, diferente da heparina comum, que age em vários pontos e precisa de mais controle.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439651976","ankiGuid":"sz?[?A.PP>"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-31595574f85fae9e","number":"1017b","sourceNumber":"1017b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"Paciente masculino de 76 anos procura a emergência devido à preocupação com resultado de exame laboratorial alterado. Nega sintomas. Apresenta história de fibrilação atrial, dislipidemia, diabetes e hipertensão arterial. Faz uso de rosuvastatina 20 mg ao dia, metformina 850 mg duas vezes ao dia e enalapril 20 mg ao dia. Apresenta FC 68/min, PA 134/80 mmHg, FR 12/min, temperatura 36,7 °C, e SpO₂ 99% em ar ambiente. Ao exame físico, não se constata equimose, hematoma ou sangramentos. Revisão de sistemas é negativa. Exame laboratorial trazido demonstra tempo de protrombina/INR = 8,5. Qual é a conduta correta para esse caso, segundo guidelines recentes?","options":{"A":"Omitir warfarina até nível terapêutico e, então, reiniciar warfarina com redução de 10-15% na dose semanal.","B":"Administrar vitamina K oral e omitir warfarina até nível terapêutico e, então, reiniciar warfarina com redução de 10-15% na dose semanal.","C":"Administrar vitamina K parenteral e omitir warfarina até nível terapêutico e, então, reiniciar warfarina com redução de 10-15% na dose semanal.","D":"Administrar plasma fresco congelado e omitir warfarina até nível terapêutico e, então, reiniciar warfarina com redução de 10-15% na dose semanal.","E":"Administrar concentrado de complexo protrombínico e omitir warfarina até nível terapêutico e, então, reiniciar warfarina com redução de 10-15% na dose semanal."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"Com RNI muito alto (8,5) mas sem nenhum sinal de sangramento, a orientação atual é: segurar a varfarina até o RNI baixar, dar uma dose de vitamina K por via ORAL (mais simples e segura que a injetável nesse cenário) e, quando o RNI normalizar, voltar com a varfarina numa dose um pouco menor.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439651977","ankiGuid":"DA6T/jS[e:"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-49455b90a084f606","number":"1018b","sourceNumber":"1018b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"A warfarina é altamente eficaz na prevenção de fenômenos tromboembólicos na FA, com redução de 64% do risco nos pacientes adequadamente tratados. NÃO podemos aceitar que:","options":{"A":"Menos da metade dos pacientes não são adequadamente tratados, por motivos que variam desde a dificuldade de controle frequente de RNI até alto risco de sangramento.","B":"Pacientes em uso de warfarina nem sempre se encontram na faixa terapêutica adequada (em geral RNI entre 5 e 6).","C":"Ocorre interação medicamentosa, principalmente antibióticos e anti-inflamatórios.","D":"Ocorre interação com alimentos, uso irregular da medicação, intercorrências clínicas agudas, entre outros."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"A pergunta pede a frase que NÃO podemos aceitar como verdadeira, ou seja, a frase ERRADA. A faixa terapêutica correta da varfarina na fibrilação atrial é RNI entre 2 e 3 — não entre 5 e 6, como diz a alternativa B. Um RNI de 5-6 seria perigosamente alto, quase um sangramento esperando pra acontecer, e não é a meta do tratamento. As outras frases (dificuldade de manter controle, interação com remédios e alimentos) estão certas.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439651978","ankiGuid":"vdKyRN+<GR"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-e3c8fcd80d41ecb5","number":"1020b","sourceNumber":"1020b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"Atualmente temos disponível uma maior variedade de anticoagulantes orais. O início da terapia com cada um deles varia bastante. A recomendação correta sobre o início do tratamento em um paciente adulto com trombose venosa profunda é o uso da:","options":{"A":"Warfarina: iniciar com 5mg/dia, sempre associado a outro anticoagulante, preferencialmente enoxaparina. Manter a associação até INR adequado e não se deve aumentar a dose de warfarina antes de 05 dias de tratamento.","B":"Rivaroxabana: iniciar 15mg de 12/12h por 15 dias, seguido de 20mg 1x/dia, sendo necessário associar outro anticoagulante nos primeiros 07 dias de tratamento.","C":"Dabigatrana: iniciar 110mg 2x/dia por 15 dias. Manutenção com 110mg 1x/dia e não há necessidade de associação com outro anticoagulante.","D":"Apixabana: iniciar com 05mg 2x/dia por 07 dias, seguido de 5mg 1x/dia e não há necessidade de associação com outro anticoagulante.","E":"Os anticoagulantes orais devem sempre ser acompanhados de uso de heparina devido ao risco de deficiência de proteína C e S."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"Atenção: o gabarito antigo marcava E, uma afirmação exagerada e falsa (nem todo anticoagulante oral precisa de heparina junto). A resposta certa é A: no início da varfarina, ela deve vir sempre acompanhada de outro anticoagulante (de preferência enoxaparina), mantendo os dois juntos até o RNI ficar na faixa certa, e sem aumentar a dose da varfarina antes de uns 5 dias — isso porque, como vimos, a varfarina no começo pode deixar o sangue mais propenso a coagular antes de proteger de verdade.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439651980","ankiGuid":"MuutV0wN%R"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-53f53353efc97ab9","number":"1021b","sourceNumber":"1021b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"A conduta para o paciente que faz uso de warfarina no período pré-operatório é:","options":{"A":"Suspender a dose de warfarina do dia anterior, iniciando heparina de baixo peso molecular em dose profilática.","B":"Ajustar a dose de warfarina para manter RNI abaixo de 1,5 no dia da cirurgia, iniciando heparina de baixo peso molecular em dose terapêutica.","C":"Suspender a dose de warfarina cinco dias antes do procedimento, iniciando heparina de baixo peso molecular em dose terapêutica.","D":"Substituir a dose de warfarina por anticoagulante oral inibidor de fator Xa trinta dias antes do procedimento."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"Atenção: o gabarito antigo marcava A, que é insuficiente (suspender a varfarina só um dia antes não dá tempo do efeito passar, já que ela demora dias pra sair do corpo). A resposta certa é C: suspender a varfarina cinco dias antes da cirurgia, cobrindo o paciente com heparina de baixo peso molecular em dose terapêutica nesse meio tempo (isso se chama 'terapia de ponte'), garantindo que ele não fique desprotegido nem com risco alto de sangrar na cirurgia.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439651981","ankiGuid":"cuD3n?k1$j"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-7aa71b68e2f5984f","number":"1023b","sourceNumber":"1023b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"Sobre os distúrbios plaquetários, a alternativa que corresponde àquela em que há deficiência da glicoproteína do complexo GpIb/V/IX é:","options":{"A":"Von Willebrand","B":"Trombastenia de Glanzmann","C":"Bernard-Soulier","D":"Síndrome de Diamond-Blackfan","E":"Síndrome de Evans"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"Atenção: o gabarito antigo marcava A, mas quem tem esse nome (deficiência do complexo GpIb/V/IX) é a síndrome de Bernard-Soulier, não a doença de Von Willebrand. A síndrome de Bernard-Soulier é como se a plaqueta perdesse o 'gancho' que usa pra grudar na parede do vaso — sem esse receptor (GpIb/V/IX), ela não consegue aderir direito, mesmo que o Fator de Von Willebrand esteja funcionando normalmente.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439651983","ankiGuid":"md!S*Yk8,k"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-75706324b73182a8","number":"1024b","sourceNumber":"1024b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"Considere as assertivas abaixo sobre vantagens do novo anticoagulante oral rivaroxabana quando comparado com warfarina. I - É usado em dose fixa (de acordo com a função renal), sem necessidade da monitorização laboratorial rotineira da anticoagulação; II - A reversão da intoxicação pelo fármaco ocorre com a administração de doses menores de vitamina K; III - O início do efeito anticoagulante é mais rápido. Quais são CORRETAS?","options":{"A":"Apenas I.","B":"Apenas II.","C":"Apenas III.","D":"Apenas I e III.","E":"I, II e III."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"Atenção: o gabarito antigo marcava A ('apenas I'), mas a frase III também está certa. A rivaroxabana tem duas vantagens reais sobre a varfarina: (I) dose fixa sem precisar fazer exame de sangue toda hora, e (III) o efeito dela começa bem mais rápido que o da varfarina (que demora dias). Já a frase II está errada — vitamina K não reverte a rivaroxabana, isso só funciona pra varfarina. Por isso a resposta certa junta I e III, alternativa D.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439651984","ankiGuid":"nc3J&,$N:,"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-5799246234c5d7b2","number":"1025b","sourceNumber":"1025b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"Assinale a alternativa que correlaciona corretamente o anticoagulante com seu principal mecanismo de ação.","options":{"A":"Warfarin - agonista da vitamina K.","B":"Heparina - agonista da antitrombina III.","C":"Dabigatrana - agonista da trombina.","D":"Rivaroxabana - inibidor indireto do fator VIIa.","E":"Fondaparinux - inibidor direto do fator VIIa."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"Por eliminação, a heparina realmente funciona 'turbinando' a antitrombina III do próprio corpo (não é bem um agonista no sentido clássico, mas é assim que costuma ser descrito nas provas) — ela dá um empurrão na antitrombina pra ela neutralizar melhor a trombina e o fator Xa. As outras alternativas trocam os conceitos: varfarina é ANTAGONISTA (não agonista) da vitamina K, dabigatrana INIBE (não é agonista d)a trombina, e assim por diante.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439651985","ankiGuid":"uCGS&eQOoD"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-826c9a21d8d20c66","number":"1026b","sourceNumber":"1026b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"Homem, 67 anos, em uso de warfarina devido a fibrilação atrial há 3 meses, em investigação etiológica. Vem ao ambulatório de anticoagulação relatando 3 idas ao pronto-socorro por equimoses e epistaxe, sempre com intoxicação cumarínica, tendo recebido vitamina K nessas ocasiões. Utiliza o medicamento em horários diversos, eventualmente com e eventualmente sem alimentação, em geral sem folhas verdes. Solicita sua orientação quanto ao uso correto da warfarina. Você orienta que:","options":{"A":"Deverá suspender a warfarina e usar ácido acetilsalicílico","B":"Deverá manter warfarina, sempre após almoço rico em folhas verdes, com controle de atividade de protrombina semestral","C":"Deverá usar em jejum e suspender folhas verdes enquanto estiver utilizando warfarina, com controle de tempo de tromboplastina parcial ativada","D":"Deverá manter medicação em jejum e poderá usar folhas verdes à vontade, desde que o faça regularmente e com controle de atividade de protrombina","E":"Como o diagnóstico foi há mais de 28 dias, não tem mais indicação de anticoagulantes ou antiagregantes"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"Atenção: o gabarito antigo marcava A (trocar por AAS), mas isso não resolve o problema real desse paciente, que é o uso irregular do remédio, e a aspirina protege muito menos contra AVC na fibrilação atrial do que a varfarina. O ensinamento certo aqui é sobre CONSISTÊNCIA: o paciente não precisa parar de comer folhas verdes, só precisa comer sempre a mesma quantidade, regularmente, tomando o remédio sempre do mesmo jeito, e acompanhando com o exame certo (atividade de protrombina/TP) — alternativa D.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439651986","ankiGuid":"DUte-C5YZ:"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-a39a8db2d3f21247","number":"1027b","sourceNumber":"1027b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"Assinale a alternativa que contém as melhores terapias para reverter anticoagulação causada pelo uso da heparina:","options":{"A":"Plasma Fresco e Crioprecipitado","B":"Vitamina K e Plasma Fresco","C":"Plasma Fresco e Sulfato de Protamina","D":"Ácido Tranexâmico e Plasma Fresco"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"Atenção: o gabarito antigo marcava A, mas plasma fresco e crioprecipitado não são o antídoto da heparina. O verdadeiro antídoto é o sulfato de protamina, que 'neutraliza' a heparina diretamente — por isso a alternativa C (que cita a protamina) é a correta entre as opções, mesmo o plasma fresco não sendo estritamente necessário na maioria dos casos.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439651987","ankiGuid":"DHwCpILbv]"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-3112a8b717d57734","number":"1028b","sourceNumber":"1028b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"Com relação aos anticoagulantes orais e seus respectivos mecanismos de ação, numere a coluna da direita de acordo com sua correspondência com a coluna da esquerda. 1. Inibidor direto da trombina. 2. Inibidor direto do fator Xa. 3. Antagonista da vitamina K. ( ) Warfarin. ( ) Rivaroxabana. ( ) Dabigatrana. ( ) Apixabana. Assinale a alternativa que apresenta a numeração CORRETA da coluna da direita, de cima para baixo.","options":{"A":"1 – 3 – 2 – 1.","B":"3 – 2 – 2 – 1.","C":"1 – 3 – 3 – 2.","D":"3 – 2 – 1 – 2.","E":"2 – 1 – 1 – 3."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"Atenção: o gabarito antigo marcava C, mas a sequência certa fica: Warfarin = antagonista da vitamina K (3), Rivaroxabana = inibidor direto do fator Xa (2), Dabigatrana = inibidor direto da trombina (1), Apixabana = inibidor direto do fator Xa (2). Juntando na ordem pedida: 3 – 2 – 1 – 2, que é a alternativa D.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439651988","ankiGuid":"C>J{uMMq$d"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-72332b1e2c353ed3","number":"1029b","sourceNumber":"1029b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"Todos os fatores de coagulação a seguir são dependentes de vitamina K, exceto:","options":{"A":"Fator X;","B":"Fator VII;","C":"Proteína C;","D":"Proteína S;","E":"Fator VIII;"},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"Atenção: o gabarito antigo marcava A ('Fator X'), mas o fator X É dependente de vitamina K. O fator que NÃO depende de vitamina K, entre os listados, é o Fator VIII (alternativa E) — os fatores dependentes de vitamina K pra guardar são: II, VII, IX, X, além das proteínas C e S.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439651989","ankiGuid":"x6+,!]Om>Z"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-99751df1d87239a1","number":"1030b","sourceNumber":"1030b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"Paciente de 35 anos, em uso de contraceptivo oral, apresenta trombose venosa profunda aguda de membro inferior. No 4º dia de uso de cumarínico apresentou necrose cutânea nos membros inferiores. Concluímos que:","options":{"A":"Houve piora do quadro trombótico","B":"Houve inibição dos fatores VIII, IX e X da coagulação","C":"Houve uma dosagem excessiva de cumarínico","D":"Houve complicação do uso do cumarínico"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"Atenção: o gabarito antigo marcava C ('dosagem excessiva'), mas isso é um mito comum — a necrose cutânea pela varfarina não é simplesmente 'dose alta demais'. É uma complicação rara e conhecida do uso do cumarínico, que acontece porque a proteína C (o 'freio' natural da coagulação) cai muito rápido no início do tratamento, formando pequenos coágulos que entopem vasinhos da pele, causando a necrose. Por isso a resposta certa é D: reconhecer isso como uma complicação conhecida do próprio remédio.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439651990","ankiGuid":"bplSSyPK{f"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-291d1cec4ea74a45","number":"1031b","sourceNumber":"1031b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"J.K.L, 67 anos, sexo feminino, balconista, está em uso de dose terapêutica de enoxaparina por trombose venosa profunda após artroplastia de joelho. Após 6º dia de uso da referida medicação, a contagem de plaquetas é de 66.000/mm³ (contagem de plaquetas antes da anticoagulação era de 212.000/mm³). Não está em uso de outros medicamentos e apresenta-se assintomática. Diante deste contexto, assinale a alternativa ERRADA:","options":{"A":"Deve-se evitar o uso de fondaparinux (inibidor indireto de fator Xa).","B":"Esta condição resulta da formação de anticorpos contra complexo heparina/fator-4-plaquetário.","C":"Inibidores diretos da trombina constituem-se em opção terapêutica.","D":"Trombose (arterial ou venosa) é uma complicação frequente."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"Atenção: o gabarito antigo marcava D, mas trombose SER uma complicação frequente da HIT é verdade (não é a frase errada). A frase realmente ERRADA é a A: o fondaparinux, ao contrário do que ela diz, é justamente uma das opções mais seguras e usadas no tratamento da HIT (por ter pouquíssima reação cruzada com o anticorpo causador), então não deveria ser evitado.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439651991","ankiGuid":"fr/n|McGfU"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-c620771a80b68f39","number":"1032b","sourceNumber":"1032b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"São fatores de coagulação sintetizados no fígado e dependentes da vitamina K:","options":{"A":"Fibrinogênio, II, VIII e X.","B":"II, V, VIII e X.","C":"II, VII, IX e X.","D":"Fibrinogênio, VIII, IX e X.","E":"VII, VIII, Fibrinogênio e IX."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"Atenção: o gabarito antigo marcava B (que inclui V e VIII, errado), mas nem o fator V nem o VIII dependem de vitamina K. Os fatores certos, feitos no fígado e que precisam de vitamina K pra funcionar, são: II, VII, IX e X (alternativa C) — um jeito de decorar é pensar no número de telefone '1972' (10, 9, 7, 2).","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439651992","ankiGuid":"l9RSl5I.)~"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-932af188d1effa24","number":"1033b","sourceNumber":"1033b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"Homem, 40 anos, faz uso cronicamente de warfarina 10 mg/dia, e possui antecedente de trombose venosa profunda. Chega ao pronto-socorro com sangramento gengival e urinário volumoso. Bom estado geral; FC = 80 bpm; PA = 110 x 80 mmHg; Hb = 12,5 g/dl; Ht = 38%; RNI = 10. O tratamento é:","options":{"A":"Transfundir plasma fresco congelado.","B":"Administrar imunoglobulina intravenosa.","C":"Administrar vitamina K.","D":"Suspender a warfarina e observar."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"Apesar do RNI estar bem alto (10) e ter sangramento nas gengivas e na urina, o paciente está com sinais vitais estáveis e hemoglobina normal (12,5) — ou seja, não é um sangramento grave o suficiente pra precisar de reversão agressiva. Por isso, a conduta mais adequada é apenas suspender a varfarina e observar de perto, deixando o corpo baixar o RNI sozinho aos poucos, sem necessidade de plasma ou imunoglobulina.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439651993","ankiGuid":"e*B2t0Xl]k"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-18985f2e2e685812","number":"1034b","sourceNumber":"1034b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"Com relação aos agentes antitrombóticos listados abaixo, qual representa um inibidor do fator Xa?","options":{"A":"Dabigatrana.","B":"Prasugrel.","C":"Rivaroxaban.","D":"Tirofiban.","E":"Femprocumona."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"Entre as opções, o único que realmente age bloqueando o fator Xa é o rivaroxaban — dabigatrana bloqueia a trombina, prasugrel e tirofiban agem nas plaquetas (não nos fatores de coagulação), e femprocumona é outro antagonista de vitamina K, como a varfarina.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439651994","ankiGuid":"isEOiF+#k*"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-9d65325383437270","number":"1035b","sourceNumber":"1035b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"Imediatamente após a administração intravenosa de 5.000 UI de heparina, seu efeito pode ser revertido com:","options":{"A":"10 mg de sulfato de protamina.","B":"20 mg de sulfato de protamina.","C":"30 mg de sulfato de protamina.","D":"40 mg de sulfato de protamina.","E":"50 mg de sulfato de protamina."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"Atenção: o gabarito antigo marcava D (40mg), mas a conta certa usa a regrinha '1mg de protamina neutraliza 100 unidades de heparina', quando aplicada logo após a dose (imediatamente). Como foram dadas 5.000 UI de heparina, a dose de protamina fica 5.000 ÷ 100 = 50mg — alternativa E.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439651995","ankiGuid":"i.k~Nk?xt?"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-280407091895f020","number":"1037b","sourceNumber":"1037b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"Para investigar alterações de hemorragia ou de coagulação, pode ser utilizada a dosagem do Tempo de Tromboplastina Parcial (TTPa), que avalia a via:","options":{"A":"Extrínseca e comum e deficiência de fatores X e XI.","B":"Extrínseca e comum e deficiência de fatores VI, IX e XI.","C":"Intrínseca e comum e deficiência de fatores VIII, IX e XI.","D":"Intrínseca e comum e deficiência de fatores V, VI, VII e X."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"Atenção: o gabarito antigo marcava D, que troca os fatores certos por errados (V, VI e VII não fazem parte da via avaliada pelo TTPa, e 'fator VI' nem existe). O TTPa avalia a via intrínseca e a via comum da coagulação, sendo sensível principalmente à falta dos fatores VIII, IX e XI — alternativa C. É o exame que fica alterado, por exemplo, na hemofilia (falta de fator VIII ou IX) e no uso de heparina.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439651997","ankiGuid":"BK}ea?4(:k"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-92bb389a49ae24c3","number":"1038b","sourceNumber":"1038b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"Sobre os distúrbios da coagulação, relacione as colunas a seguir: (A) Uso terapêutico de heparina; (B) Uso terapêutico de cumarínico; (C) Prolongamento do TP e TTPa; (D) Prolongamento do TTPa; (E) Anormalidade isolada do TP. ( ) Deficiência do fator VII; ( ) Hemofilias ou deficiência do fator XI; ( ) Deficiência de fatores V, X, II, ou fibrinogênio; ( ) Alargamento do TP; ( ) Alargamento do TTPa. Assinale a alternativa correta:","options":{"A":"E-D-C-B-A.","B":"E-B-C-A-D.","C":"D-E-C-A-B.","D":"C-E-D-A-B.","E":"D-C-E-B-A."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"É um joguinho de combinar cada situação com o exame que ela mais afeta: falta do fator VII afeta só a via extrínseca, alterando só o TP sozinho (E). Falta do fator XI (ou hemofilias, que afetam VIII/IX) mexe só na via intrínseca, alterando só o TTPa (D). Falta de fatores da via comum (V, X, II, fibrinogênio) bagunça as duas vias, alterando TP E TTPa juntos (C). E, na prática clínica, quem alarga o TP de propósito é o uso terapêutico de cumarínico/varfarina (B), enquanto quem alarga o TTPa de propósito é o uso terapêutico de heparina (A). Juntando na ordem pedida: E-D-C-B-A.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439651998","ankiGuid":"HyamK[#)Vd"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-7a9e468c13b5694d","number":"1039b","sourceNumber":"1039b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"Em relação a paciente submetido a profilaxia para trombose venosa profunda por tempo prolongado com heparina não fracionada, assinale a alternativa ERRADA:","options":{"A":"Esta droga é clareada principalmente pelos receptores situados no endotélio, macrófagos e rins","B":"Pode apresentar trombocitopenia autoimune","C":"Seu mecanismo de ação se faz por inativação de vários fatores da cascata de coagulação, sendo os mais sensíveis a trombina e o fator Xa","D":"Sua maior afinidade por proteínas plasmáticas lhe confere maior biodisponibilidade e maior meia-vida plasmática"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"Atenção: o gabarito antigo marcava C (que na verdade está certa: a heparina não fracionada mesmo age inibindo principalmente a trombina e o fator Xa). A frase realmente ERRADA é a D: na real, é o CONTRÁRIO do que ela diz — a heparina não fracionada se liga MUITO às proteínas do plasma, e isso é justamente o que deixa o efeito dela IMPREVISÍVEL, com biodisponibilidade mais BAIXA e variável (não maior), sendo por isso que ela precisa de exames de sangue frequentes pra ajustar a dose, diferente da heparina de baixo peso molecular.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439651999","ankiGuid":"NvXFUtPFeJ"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-01ae6cee0ed07750","number":"1040b","sourceNumber":"1040b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"A warfarina é um dos medicamentos mais utilizados em caso de necessidade de anticoagulação prolongada. A dose inicial, em geral, é de 5 mg por dia, devendo ser ajustada até manter um INR entre:","options":{"A":"1,0 e 1,5.","B":"1,5 e 2,0.","C":"2,0 e 3,0","D":"3,0 e 3,5.","E":"3,5 e 4,0."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"A meta de RNI (INR) pra maioria dos pacientes em uso de varfarina, incluindo essa faixa de dose inicial de 5mg, fica entre 2,0 e 3,0 — nem baixo demais (sem proteção) nem alto demais (risco de sangramento).","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439652000","ankiGuid":"n8B-1WlnR^"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-f1060e82fceb1346","number":"1041b","sourceNumber":"1041b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"Com relação às drogas anticoagulantes é correto afirmar que:","options":{"A":"As heparinas de baixo peso molecular são eficientes na profilaxia da trombose venosa, mas não no tratamento da trombose já estabelecida.","B":"A anticoagulação realizada com heparina intravenosa deve ser monitorada com medidas diárias da atividade da protrombina.","C":"A terapia anticoagulante com dicumarínicos deve sempre ser iniciada com doses maiores do que a dose de manutenção (dose de ataque).","D":"O uso de heparina é contra-indicado no primeiro e no terceiro trimestres da gravidez.","E":"Os dicumarínicos podem apresentar efeito pró-coagulante no início do tratamento."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"Atenção: o gabarito antigo marcava C, que hoje é considerado ultrapassado (não se recomenda mais 'dose de ataque' de varfarina, isso aumenta risco de complicação). A frase realmente correta é a E: os dicumarínicos (como a varfarina) podem sim ter um efeito PRÓ-coagulante logo no início do tratamento — a mesma ideia da primeira questão desse bloco, quando a proteína C cai antes dos fatores de coagulação, deixando o sangue temporariamente mais propenso a formar coágulos.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439652001","ankiGuid":"luOc47&GbR"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-24f0a9275d7d06b1","number":"1043b","sourceNumber":"1043b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"Homem de 55 anos, paraplégico por acidente automobilístico há 15 anos, é internado por pneumonia adquirida na comunidade. Está no oitavo dia de internamento hospitalar (DIH), com boa resposta ao antibiótico endovenoso, quando foi observado edema isolado de perna esquerda. Ultrassonografia com doppler evidenciou trombose venosa profunda na perna edemaciada, mesmo com uso diário de enoxaparina 40mg via SC. Os exames da admissão mostravam plaquetas: 300.000/mm³. O exame de hoje (8º DIH) evidencia plaquetas: 60.000/mm³. Paciente não fez uso de quaisquer medicamentos nos 12 meses prévios ao internamento. Qual conduta deve ser adotada nesse momento?","options":{"A":"Suspender enoxaparina e iniciar warfarina.","B":"Trocar enoxaparina por fondaparinux.","C":"Manter enoxaparina em 1mg/kg de peso 2x/dia.","D":"Trocar enoxaparina por heparina não fracionada."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"Atenção: o gabarito antigo marcava A (trocar por varfarina), o que é perigoso aqui — esse paciente desenvolveu uma trombose NOVA mesmo estando com enoxaparina em dose terapêutica, e as plaquetas caíram bastante (300 mil pra 60 mil): é a cara da HIT (trombocitopenia induzida por heparina) com trombose associada. Iniciar varfarina agora, com plaquetas ainda baixas, pode causar necrose de pele/gangrena. A conduta certa é trocar por um anticoagulante que não seja da família heparina, como o fondaparinux — alternativa B.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439652003","ankiGuid":"bK>P8So@O/"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-bf7cdf7a91e66814","number":"1044b","sourceNumber":"1044b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"Em relação à terapia anticoagulante, é correto afirmar:","options":{"A":"A enoxaparina tem a vantagem de não necessitar de controle do TTPa e pode ser usada em paciente com disfunção renal leve a moderada, bastando fazer o ajuste de dose recomendado em bula.","B":"A enoxaparina tem menor risco de levar a plaquetopenia e trombose relacionadas à heparina do que a heparina não fracionada, entretanto não pode ser usada no tratamento dessas condições.","C":"O início do tratamento com warfarina requer associação com heparina ou heparinoides nos dois primeiros dias. Caso o RNI não atinja a faixa ideal, deve-se aumentar a dose da heparina até que ele alcance a faixa terapêutica desejada.","D":"Os novos anticoagulantes orais, como rivaroxabana e dabigatrana, têm a grande vantagem de não necessitarem de controle do RNI ou TTPa, mas só são indicados para pacientes com prótese valvar metálica."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"Atenção: o gabarito antigo marcava C, que contém um erro (não se 'aumenta a dose de heparina' esperando o RNI subir — isso não faz sentido, já que a heparina é ajustada por outro exame, o TTPa, e não pelo RNI). A frase correta é a A: a enoxaparina realmente não precisa de controle rotineiro de TTPa, e pode ser usada com ajuste de dose em quem tem função renal só um pouco reduzida (leve a moderada) — em disfunção renal grave, aí sim prefere-se trocar por heparina não fracionada.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439652004","ankiGuid":"o>tzL1S5Q-"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-cc9196433301d54a","number":"1045b","sourceNumber":"1045b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"Uma mulher de 48 anos foi diagnosticada com trombose venosa profunda em seu membro inferior esquerdo. Um clínico recém-formado está em dúvida na escolha do anticoagulante a ser prescrito. A respeito da heparina de baixo peso molecular, qual das opções abaixo NÃO consiste em uma vantagem em relação à heparina não fracionada?","options":{"A":"Melhor biodisponibilidade","B":"Clearance dose-dependente","C":"Maior meia-vida após injeção subcutânea.","D":"Menor risco de trombocitopenia induzida pela heparina.","E":"Efeito anticoagulante previsível."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"Atenção: o gabarito antigo marcava A, mas 'melhor biodisponibilidade' é justamente uma vantagem real da heparina de baixo peso molecular (não é a resposta certa pra 'o que NÃO é vantagem'). A opção que descreve algo que NÃO é vantagem da heparina de baixo peso molecular é a B: 'clearance dose-dependente' — isso é uma característica chata da heparina NÃO fracionada (que se elimina de um jeito imprevisível dependendo da dose). A vantagem real da heparina de baixo peso molecular é justamente ter uma eliminação mais previsível, sem essa dependência complicada da dose.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439652005","ankiGuid":"JeEO|F`f9o"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-93c1e72f03928c94","number":"1046b","sourceNumber":"1046b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"Uma senhora de 75 anos é admitida na emergência com quadro de dispneia de início progressivo. Alega história prévia de hipertensão arterial e fibrilação atrial permanente. Realiza laboratório com evidência de INR de 9.5. Qual das condutas abaixo é a mais apropriada neste momento:","options":{"A":"Vitamina K 10 mg IV","B":"Vitamina K 01 ampola IM","C":"Vitamina K 5 mg oral","D":"Plasma fresco","E":"Vitamina K 10mg IV + plasma fresco"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"Atenção: o gabarito antigo marcava D (plasma fresco), mas repare que a questão não menciona NENHUM sinal de sangramento — só falta de ar (provavelmente do coração, já que ela tem hipertensão e fibrilação atrial). Sem sangramento, não faz sentido usar plasma fresco (que é reservado pra sangramentos importantes). O certo, com RNI tão alto (9,5) mesmo sem sangrar, é dar vitamina K por via oral — alternativa C — que é mais simples, segura e suficiente pra baixar o RNI aos poucos.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439652006","ankiGuid":"jYQ0`uR.qU"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-a30b9137a1eb2ec9","number":"1047b","sourceNumber":"1047b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"As heparinas podem ser usadas na gravidez?","options":{"A":"Sim, tanto a heparina não fracionada quanto as de baixo peso molecular.","B":"Não, nenhuma heparina pode ser usada na gravidez.","C":"Apenas a heparina não fracionada.","D":"Apenas as heparinas de baixo peso molecular.","E":"Nenhuma das anteriores."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"Atenção: o gabarito antigo marcava C ('apenas a não fracionada'), mas hoje em dia a heparina de baixo peso molecular é, na verdade, a PREFERIDA na gravidez (mais previsível, mais segura, menos efeitos colaterais). A resposta certa é A: tanto a heparina não fracionada quanto a de baixo peso molecular podem ser usadas na gravidez, porque nenhuma das duas atravessa a placenta (diferente da varfarina, que é proibida, principalmente no primeiro trimestre).","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439652007","ankiGuid":"ytLm@t[5LE"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-df5fdc778450f2cf","number":"1048b","sourceNumber":"1048b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"Paciente de 62 anos foi submetido à cirurgia de prótese total de quadril esquerdo há 5 dias. Em uso de tramadol, heparina não fracionada e ranitidina. Evolui com sinais de trombose venosa profunda do membro operado. No pré-operatório a contagem de plaquetas era 240.000/mm³ e agora 70.000/mm³. Assinale a opção mais correta neste caso:","options":{"A":"Trata-se de trombocitopenia induzida por heparina. Devemos suspender a heparina em uso imediatamente e iniciar uso de warfarina.","B":"Um episódio de trombocitopenia induzida por heparina é contraindicação absoluta para uso posterior de qualquer forma de heparina.","C":"Trata-se de trombocitopenia induzida por heparina, que é facilitada pela associação com tramadol. Devemos suspender a heparina em uso e iniciar heparina de baixo peso molecular.","D":"A conduta pode ser mantida, pois o nível de plaquetas não é crítico.","E":"Esta síndrome é causada por anticorpos contra complexo antigênico formado de fator plaquetário 4 (FP 4) e heparina, devendo suspender a heparina e iniciar fondaparinux."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"Esse é o quadro típico de HIT: queda importante das plaquetas (240 mil para 70 mil) alguns dias depois de começar a usar heparina, associada a uma trombose nova. A causa é o corpo formar anticorpos contra o complexo que a heparina forma com uma proteína das plaquetas (o fator plaquetário 4). O tratamento certo é suspender toda heparina e trocar por um anticoagulante de outra família, como o fondaparinux — nunca continuar usando heparina nem partir direto pra varfarina enquanto as plaquetas estão baixas.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439652008","ankiGuid":"Lng~GvKEh*"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-c48a05b25a631df6","number":"1049b","sourceNumber":"1049b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"Paciente de 54 anos em anticoagulação com cumarínico há 3 meses, devido à trombose venosa profunda, cursou com sangramento genital intenso, procurando atendimento médico. Avaliada pelo plantonista, que encontrou a paciente pálida, com frequência cardíaca de 120 bpm e hipotensão de 80 x 40 mmHg. Exames laboratoriais mostravam hemoglobina: 8,2 mg/dL; RNI: > 10. Portadora de hipertensão arterial e miomatose uterina. Após prescrição de hidratação venosa com 2000 ml de cristalóide, a paciente evoluiu com melhora da pressão arterial para 110 x 70 mmHg, frequência cardíaca caiu para 100 bpm e apareceram crepitações em bases pulmonares bilateralmente. A paciente ainda mantinha quadro de sangramento ativo. Considerando o caso clínico descrito, assinale a alternativa MAIS adequada para o controle do sangramento.","options":{"A":"Administrar vitamina K intravenosa de 12/12 horas.","B":"Transfundir plasma fresco congelado na dose de 15ml/kg de peso.","C":"Administrar complexo protrombínico na dose de 25UI/kg.","D":"Realizar histerectomia de urgência para tratamento da miomatose uterina."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"Essa paciente está sangrando muito, com RNI acima de 10, e mesmo depois de hidratação ainda sangra, além de já mostrar sinais de estar recebendo líquido demais (crepitações no pulmão). Nesse cenário, o complexo protrombínico é a melhor escolha: ele repõe rapidamente os fatores de coagulação que a varfarina bloqueou, em um volume bem menor de líquido do que o plasma fresco precisaria — importante justamente porque essa paciente já não está tolerando bem mais volume.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439652009","ankiGuid":"nxNWOO&!hx"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-2319bddc078ef712","number":"1050b","sourceNumber":"1050b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"Paciente feminina, com fibrilação atrial crônica e prótese mecânica de válvula mitral, está anticoagulada a pleno com cumarínico. Esta paciente será submetida a uma cirurgia eletiva com risco alto de sangramento. Qual a conduta mais adequada a ser seguida?","options":{"A":"Manter a anticoagulação oral inalterada e cuidar na hemostasia cirúrgica.","B":"Suspender o anticoagulante oral uma semana antes do procedimento.","C":"Trocar o anticoagulante oral temporariamente por heparina e suspender esta antes do procedimento.","D":"Trocar o anticoagulante oral por AAS 200 mg/dia uma semana antes do procedimento;","E":"Trocar o anticoagulante oral por AAS 200 mg/dia e clopidogrel 75 mg/dia uma semana antes do procedimento."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"Atenção: o gabarito antigo marcava B (simplesmente parar uma semana antes, sem mais nada), mas isso deixaria essa paciente de alto risco (prótese de válvula mecânica) desprotegida por muitos dias sem nenhum anticoagulante. A conduta certa é a C: trocar temporariamente a varfarina por heparina (fazendo a 'ponte'), e só parar a heparina pouco antes da cirurgia — assim ela fica protegida contra trombose na válvula quase até a hora do procedimento, e o efeito anticoagulante para bem perto da cirurgia, reduzindo o risco de sangramento.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439652010","ankiGuid":"?/ybUoA]1"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-24da852bf6410a75","number":"1051b","sourceNumber":"1051b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"A warfarina é um anticoagulante oral prescrito para anticoagulação ambulatorial dos pacientes. Qual o teste mais usado para monitorizar seu uso?","options":{"A":"Tempo de Protrombina (TP).","B":"Plaquetas.","C":"Tempo de coagulação.","D":"Hemograma.","E":"Tempo de Tromboplastina Parcial (TTP)."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"Atenção: o gabarito antigo marcava B ('Plaquetas'), mas repare que a própria alternativa A já diz 'Tempo de Protrombina (TP)' — esse é literalmente o teste certo pra acompanhar a varfarina, e é dele que vem o cálculo do RNI que a gente usa o tempo todo pra ajustar a dose.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439652011","ankiGuid":"msrDBmx`hH"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-8a5b1f395f618999","number":"1052b","sourceNumber":"1052b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"Qual das seguintes opções abaixo menciona o melhor teste para acompanhar terapia heparínica?","options":{"A":"Tempo de protrombina.","B":"Tempo parcial de tromboplastina.","C":"Tempo de sangramento.","D":"Contagem de plaquetas."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"O melhor teste pra acompanhar quem está usando heparina (a não fracionada, injetada na veia) é o TTPa (tempo parcial de tromboplastina ativada) — ele mostra se a dose está adequada, alta demais (risco de sangrar) ou baixa demais (sem proteção).","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439652012","ankiGuid":"e)QvJ!qmeg"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-3da3e8e87ee50fb8","number":"1054b","sourceNumber":"1054b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"No que se refere à dengue, doença que afeta milhões de pessoas no mundo, julgue o item subsecutivo. O Tempo de Protrombina (TP) avalia a via extrínseca da cascata de coagulação, sendo altamente sensível aos fatores II, V, VII, IX e X.","options":{"A":"Certo.","B":"Errado."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"Atenção: o gabarito antigo marcava 'Certo', mas a frase tem um erro escondido: o TP (Tempo de Protrombina) avalia mesmo a via extrínseca da coagulação, só que ele é sensível aos fatores II, V, VII e X — o fator IX NÃO entra nessa lista, porque ele pertence à via intrínseca (a que é avaliada pelo TTPa, não pelo TP). Por incluir o fator IX errado, a frase está errada — resposta B.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439652014","ankiGuid":"PqN)[iJ*lk"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-f027e7283c8a2a78","number":"1056b","sourceNumber":"1056b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"Em relação às drogas anticoagulantes, assinale a alternativa que contém um inibidor direto do fator Xa.","options":{"A":"Dabigatrana.","B":"Rivaroxabana.","C":"Warfarina.","D":"Rituximab.","E":"Clopidogrel."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"Atenção: o gabarito antigo marcava C ('Warfarina'), mas a varfarina não inibe o fator Xa — ela bloqueia a produção de vários fatores dependentes de vitamina K, por um mecanismo totalmente diferente. O verdadeiro inibidor direto do fator Xa entre as opções é a rivaroxabana — alternativa B.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439652016","ankiGuid":"k_^gMMwMDJ"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-a618108a8eae2c49","number":"1057b","sourceNumber":"1057b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"Qual é o antídoto da heparina?","options":{"A":"Vitamina K","B":"Estrógeno","C":"Sulfato de protamina","D":"Gluconato de cálcio","E":"Plasmina"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"O antídoto da heparina é o sulfato de protamina — ele se liga diretamente à heparina no sangue e neutraliza o efeito dela, agindo bem rápido.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439652017","ankiGuid":"NcuQchF?6a"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-8ac742eff3bc306a","number":"1058b","sourceNumber":"1058b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"Sobre a trombocitopenia induzida pela heparina é correto afirmar que:","options":{"A":"Nesses casos a transfusão de plaquetas é bem aplicada.","B":"A heparina deve ser substituída por warfarina enquanto houver a trombocitopenia.","C":"É mais comum a sua ocorrência quando se utiliza heparina de baixo peso molecular.","D":"É um processo mediado por anticorpos dirigidos contra neoantígenos de complexos heparina-PF4.","E":"Acontece mais comumente em homens em comparação com mulheres, e nos pacientes clínicos em relação aos cirúrgicos."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"Atenção: o gabarito antigo marcava A, mas transfundir plaquetas na HIT é perigoso (pode alimentar ainda mais a formação de coágulos!) e por isso é evitado, não 'bem aplicado'. A frase correta é a D: a HIT é causada por anticorpos que o corpo forma contra um complexo estranho feito pela junção da heparina com uma proteína das plaquetas (o fator plaquetário 4, ou PF4) — esses 'neoantígenos' enganam o sistema imune, que passa a atacar as próprias plaquetas.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439652018","ankiGuid":"tH;e2~f#:+"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-03aaa0aa7c6faf77","number":"1059b","sourceNumber":"1059b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"Qual das drogas abaixo é um anticoagulante que tem como mecanismo de ação a inibição direta da trombina?","options":{"A":"Enoxaparina.","B":"Dabigatran.","C":"Warfarina.","D":"Estreptoquinase.","E":"Clopidogrel."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"O dabigatran é o exemplo clássico de anticoagulante que age bloqueando diretamente a trombina (por isso é chamado de 'inibidor direto da trombina') — diferente da enoxaparina e da varfarina, que agem de outras formas.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439652019","ankiGuid":"J,Z:F<fe,h"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-cfe1c7799ccffc07","number":"1060b","sourceNumber":"1060b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"Um paciente de 65 anos encontra-se internado por sepse grave em UTI. Além de antibióticos, foram prescritos enoxaparina subcutânea e ranitidina IV para profilaxia de trombose venosa profunda e de úlcera de estresse, respectivamente. No 9º dia de admissão, foram observadas lesões necróticas na pele do abdome. A contagem de plaquetas em hemograma de controle é de 40.000/mm³ (na admissão era de 80.000/mm³). O restante do hemograma é normal, compatível com a resolução clínica do seu quadro infeccioso. Não são observados sangramentos espontâneos.\n\nQue conduta é a mais recomendada dentre as descritas abaixo?","options":{"A":"Substituição da enoxaparina por heparina não fracionada.","B":"Substituição da enoxaparina por warfarina.","C":"Suspensão da enoxaparina.","D":"Suspensão da ranitidina."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":["question_bank/media/hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes/paste-63b827040d0c1c9a57ae33056987a5257a30cee7.png"],"optionImages":{},"commentImages":[],"comment":"Atenção: o gabarito antigo marcava B (trocar por varfarina), mas isso é perigoso nesse momento — esse paciente tem lesões necróticas na pele e as plaquetas caindo muito (80 mil para 40 mil) enquanto usa enoxaparina, um quadro bem sugestivo de HIT. Trocar direto por varfarina, com as plaquetas ainda baixas, pode piorar a necrose de pele. A conduta mais segura entre as opções é suspender a enoxaparina (removendo o agente causador), evitando também continuar ou trocar por outro tipo de heparina.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439652020","ankiGuid":"GoR#Mj>/-8"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-908ea652ff76d6f8","number":"1061b","sourceNumber":"1061b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"Paciente de 45 anos, internado há 10 dias por fratura complexa de fêmur. Está em uso de heparina não fracionada (heparina sódica) para profilaxia de trombose venosa profunda desde o início do internamento. Seus exames iniciais revelam Hb = 12,4 g/dl, Leucócitos = 12.350/mm³ e Plaquetas 190.000/mm³. No décimo dia do internamento, um novo hemograma mostrou Hb = 9,5 g/dl, Leucócitos = 7.200/mm³ e Plaquetas = 65.000/mm³. Não há sangramentos nem sinais de trombose venosa. Além de suspender o uso de heparina, o que mais deve ser feito?","options":{"A":"Iniciar argatroban.","B":"Transfundir plaquetas.","C":"Associar prednisona.","D":"Iniciar warfarina."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"Atenção: o gabarito antigo marcava B (transfundir plaquetas), mas isso é perigoso na HIT — pode alimentar ainda mais a formação de coágulos! Esse paciente, com plaquetas caindo bastante (190 mil para 65 mil) enquanto usa heparina, tem HIT bem provável, mesmo sem sangramento ou trombose evidente ainda. Como o risco de trombose continua alto mesmo assim, a conduta certa é iniciar um anticoagulante alternativo à heparina, como o argatroban — alternativa A.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439652021","ankiGuid":"gwmjfz^A&G"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-735e5aaa02a81e88","number":"1062b","sourceNumber":"1062b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"Sobre a trombocitopenia induzida por administração de heparina, é correto afirmar que ela:","options":{"A":"É autolimitada, com a contagem de plaquetas abaixo de 100.000 e ocorre nos tratamentos com duração maior que 6 meses.","B":"Ocorre entre o quinto e décimo dias de tratamento e é decorrente de processo autoimune dependente de IgG.","C":"É transitória, pouco comum no início do tratamento e reversível com a substituição do agente anticoagulante.","D":"É restrita ao uso de heparinas de baixo peso molecular."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"Atenção: o gabarito antigo marcava C, mas dizer que é 'pouco comum no início do tratamento' é estranho, já que o início (dia 5 a 10) é justamente quando ela mais aparece. A frase correta é a B: a trombocitopenia induzida por heparina costuma aparecer entre o 5º e o 10º dia de tratamento, e acontece porque o sistema imune do paciente cria anticorpos do tipo IgG contra a heparina — um processo autoimune.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439652022","ankiGuid":"L{0BJ)nCQf"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-8b4a94c84f8f5c35","number":"1063b","sourceNumber":"1063b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"Paciente de 60 anos encontra-se internado para tratamento de trombose venosa profunda em membro inferior direito com boa resposta no 3º dia de internamento hospitalar. No quarto dia passou a apresentar petéquias difusas com nível de plaquetas de 3.500 (esse valor era 325.000 no primeiro dia de internamento). Está somente com heparinização plena com heparina não fracionada. Recebeu, então, o diagnóstico de trombocitopenia induzida por heparina. Qual a conduta mais adequada no momento?","options":{"A":"Suspender a heparina e transfundir plaquetas.","B":"Suspender a heparina e iniciar warfarina.","C":"Suspender a heparina e iniciar enoxaparina.","D":"Suspender a heparina e não utilizar outro anticoagulante.","E":"Suspender a heparina e iniciar argatroban"},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"Atenção: o gabarito antigo marcava B (trocar por varfarina), mas isso é arriscado logo depois de suspender a heparina numa HIT com plaquetas tão baixas (risco de necrose de pele/gangrena). A conduta certa é suspender a heparina e iniciar um anticoagulante direto da trombina, como o argatroban — alternativa E — que protege o paciente da trombose sem depender da via da heparina.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439652023","ankiGuid":"ekyAmVC}fp"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-f616c032b93ff761","number":"1002b","sourceNumber":"1002b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"Homem, 32 anos, internado há três dias após fratura de tíbia por acidente automobilístico, apresentou quadro de dispneia súbita. Foi feito o diagnóstico de tromboembolismo pulmonar e iniciada a anticoagulação plena com heparina não fracionada.\n\nNo dia seguinte, após apresentar fraqueza em dimídio direito, foi suspensa a heparina e realizada tomografia computadorizada de crânio. A CONDUTA É:","options":{"A":"Prescrever vitamina K.","B":"Retomar a heparina não fracionada.","C":"Prescrever plasma fresco congelado.","D":"Prescrever protamina."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":["question_bank/media/hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes/paste-6646f84b26d3a644c93c68145ea519f232bce188.png"],"optionImages":{},"commentImages":[],"comment":"A fraqueza súbita de um lado do corpo, num paciente recém-anticoagulado com heparina em dose plena, faz pensar logo em sangramento dentro do crânio (e por isso pediram a tomografia). Assim que se suspeita disso, a heparina precisa ser revertida rapidamente com o antídoto certo: sulfato de protamina — alternativa D.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439693074","ankiGuid":"hF}huIo1ts"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-42c84acaf1996f11","number":"1003b","sourceNumber":"1003b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"Paciente de 48 anos, portador de cardiomiopatia hipertrófica em forma apical (Yamaguchi) e com fibrilação atrial, vinha em uso de succinato de metoprolol 100 mg e dabigatrana 150 mg de 12/12 horas para controle de sintomas. Apresentou hematúria maciça, com instabilidade hemodinâmica e choque hipovolêmico. Após estabilização clínica e transfusão de hemoderivados, realizou TC que evidenciou imagem sugestiva de neoplasia de bexiga. Ao ser avaliado por um urologista, este indicou abordagem cirúrgica de urgência. Antes de iniciar a cirurgia, é necessário fazer a reversão da anticoagulação com:","options":{"A":"Protamina.","B":"Andexanet alfa.","C":"Complexo protrombínico.","D":"Idarucizumabe."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"Atenção: o gabarito antigo marcava B (andexanet alfa), mas esse antídoto serve pra reverter os inibidores do fator Xa (como rivaroxabana e apixabana) — não serve pra dabigatrana, que é um inibidor DIRETO da trombina, um mecanismo diferente. O antídoto certo da dabigatrana é o idarucizumabe — alternativa D — que se liga diretamente à dabigatrana e neutraliza seu efeito rapidamente, essencial antes de uma cirurgia de urgência.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439693075","ankiGuid":"L>0[.g9-aw"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-f40052d8d21dee25","number":"1004b","sourceNumber":"1004b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"Primigesta, 34 anos, com 16 semanas de gestação, comparece ao ambulatório de gestação de alto risco para iniciar seguimento de pré-natal. Sem queixas clínicas e obstétricas. Antecedentes pessoais: cardiopatia reumática com válvula metálica, classe funcional I, em uso de warfarina 5 mg uma vez ao dia. O resultado do RNI (Razão Normalizada Internacional) colhido há 1 semana apresenta valor de 1,8 vezes o controle. Qual é a melhor conduta com relação à anticoagulação dessa paciente?","options":{"A":"Aumentar a dose de warfarina para 7,5 mg uma vez ao dia.","B":"Suspender warfarina e iniciar dose terapêutica de enoxaparina.","C":"Manter a dose de warfarina 5 mg uma vez ao dia.","D":"Suspender warfarina e iniciar AAS 100 mg uma vez ao dia."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"Gestante com válvula cardíaca mecânica precisa de anticoagulação forte durante toda a gravidez, porque o risco de a válvula entupir (trombose) é alto e perigoso pra ela e pro bebê. Depois do primeiro trimestre (quando passa a fase de maior risco da varfarina causar má-formação no bebê), muitos serviços optam por manter a varfarina, já que ela protege melhor a válvula do que outras opções — desde que a dose seja bem ajustada e a paciente monitorada de perto. Esse é um tema com alguma divergência entre diferentes diretrizes (varfarina x heparina de baixo peso molecular nesse período), então vale sempre conferir o protocolo do seu serviço.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439693076","ankiGuid":"z`;lpN4s.5"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-7ad8918382c770be","number":"1005b","sourceNumber":"1005b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"São considerados anticoagulantes, por bloqueio do fator Xa, EXCETO:","options":{"A":"Rivaroxabana.","B":"Edoxabana.","C":"Enoxaparina.","D":"Dabigatrana."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"Atenção: o gabarito antigo marcava A ('Rivaroxabana'), mas ela realmente bloqueia o fator Xa, então não pode ser a exceção. Quem NÃO bloqueia o fator Xa, entre as opções, é a dabigatrana — ela tem um mecanismo diferente, bloqueando diretamente a trombina (fator IIa) — alternativa D.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439693077","ankiGuid":"sB7eAv$l=c"},{"id":"anki-hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes-5f2eb302ed51ec77","number":"1006b","sourceNumber":"1006b","collectionBlock":"anki:hematologia-hemostasia-i-conceitos-basicos-e-anticoagulantes","collectionLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","documentBlock":"","area":"Hematologia","specialty":"Hematologia","topic":"Hemostasia I - Conceitos Básicos e Anticoagulantes","subtopic":"","stem":"Mulher de 55 anos faz uso crônico de warfarina 5mg ao dia, devido a trombose venosa profunda há 4 meses. A paciente é diabética e apresenta uma infecção grave na perna. Devido a piora do quadro e odor, ela foi à emergência, onde foi indicada amputação suprapatelar, devido a gangrena úmida. INR do dia: 3. O que a equipe cirúrgica deve fazer para diminuir o risco de sangramento durante a amputação?","options":{"A":"Suspender o warfarina, transfundir plaquetas.","B":"Suspender o warfarina, aplicar sulfato de protamina.","C":"Suspender o warfarina, realizar a amputação em 5 dias.","D":"Suspender o warfarina, aplicar vitamina K e reservar plasma."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 3 (Quarta-feira)__10 - Hematologia.apkg","sourceLabel":"Anki · Hemostasia I - Conceitos Básicos e Anticoagulantes","images":[],"optionImages":{},"commentImages":[],"comment":"Atenção: o gabarito antigo marcava B (sulfato de protamina), mas a protamina é o antídoto da HEPARINA, não da varfarina — não teria efeito nenhum aqui! Pra reverter rapidamente o efeito da varfarina antes de uma cirurgia urgente, o certo é aplicar vitamina K (que ajuda o fígado a voltar a produzir os fatores de coagulação) e deixar plasma reservado, caso seja preciso repor os fatores mais rápido durante a cirurgia — alternativa D.","tags":["Hematologia","Hemostasia I - Conceitos Básicos e Anticoagulantes","Anki"],"ankiNoteId":"1742439693078","ankiGuid":"cF&%yn0$BT"}]};
